from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied, NotFound
from rest_framework import status
from organizations.models import Organization, OrganizationOwner, OrganizationUser

class TransferOrganizationOwnershipView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, slug: str):
        try:
            target_org = Organization.objects.get(slug=slug)
            current_owner = target_org.owner
        except Organization.DoesNotExist:
            raise NotFound("Organization not found")

        # Verify that request.user is the current verified owner of the organization
        if not current_owner or current_owner.organization_user.user != request.user:
            raise PermissionDenied("Only the current organization owner can transfer ownership")

        new_owner_user_id = request.data.get('new_owner_id')
        try:
            new_owner_membership = OrganizationUser.objects.get(
                organization=target_org,
                user_id=new_owner_user_id
            )
        except OrganizationUser.DoesNotExist:
            return Response({'error': 'Target user is not a member of this organization'}, status=status.HTTP_400_BAD_REQUEST)

        current_owner.organization_user = new_owner_membership
        current_owner.save()

        return Response({'status': 'ownership_transferred', 'new_owner': new_owner_user_id})
